<template><div class="page"><div class="page-head"><div><h1 class="page-title">运营概览</h1><div class="page-subtitle">当前公众号的核心运营入口</div></div></div><div class="cards"><div class="surface stat"><span>公众号</span><b>{{ account?.name || '-' }}</b></div><div class="surface stat"><span>素材数量</span><b>{{ count }}</b></div><div class="surface stat"><span>粉丝同步</span><el-button type="primary" plain @click="sync">立即同步</el-button></div></div></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';import{session}from'@/lib/session';const account=computed(()=>session.account),count=ref('-');onMounted(async()=>{const r=await api.materialCount();count.value=Object.values(r.data||r).reduce((a,b)=>a+(Number(b)||0),0)});async function sync(){await api.syncFollowers();ElMessage.success('粉丝同步任务已启动')}</script>
<style scoped>.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat{min-height:130px;padding:22px;display:flex;flex-direction:column;align-items:start;justify-content:space-between}.stat span{color:#7b879e;font-size:13px}.stat b{font-size:24px}</style>
